41	void
42	UA_SecureChannel_init(UA_SecureChannel *channel) {
43	    /* Linked lists are also initialized by zeroing out */
44	    memset(channel, 0, sizeof(UA_SecureChannel));
45	    channel->state = UA_SECURECHANNELSTATE_FRESH;
46	    TAILQ_INIT(&channel->messages);
47	}
