49	UA_StatusCode
50	UA_SecureChannel_setSecurityPolicy(UA_SecureChannel *channel,
51	                                   const UA_SecurityPolicy *securityPolicy,
52	                                   const UA_ByteString *remoteCertificate) {
53	    /* Is a policy already configured? */
54	    if(channel->securityPolicy)
55	        return UA_STATUSCODE_BADINTERNALERROR;
56	
57	    channel->securityPolicy = securityPolicy;
58	    UA_StatusCode retval;
59	    if(channel->securityPolicy->certificateVerification != NULL) {
60	        retval = channel->securityPolicy->certificateVerification->
61	            verifyCertificate(channel->securityPolicy->certificateVerification->context,
62	                              remoteCertificate);
63	
64	        if(retval != UA_STATUSCODE_GOOD)
65	            return retval;
66	    } else {
67	        UA_LOG_WARNING(channel->securityPolicy->logger, UA_LOGCATEGORY_SECURITYPOLICY,
68	                       "No PKI plugin set. Accepting all certificates");
69	    }
70	
71	    retval = securityPolicy->channelModule.
72	        newContext(securityPolicy, remoteCertificate, &channel->channelContext);
73	    if(retval != UA_STATUSCODE_GOOD)
74	        return retval;
75	
76	    retval = UA_ByteString_copy(remoteCertificate, &channel->remoteCertificate);
77	    if(retval != UA_STATUSCODE_GOOD)
78	        return retval;
79	
80	    UA_ByteString remoteCertificateThumbprint = {20, channel->remoteCertificateThumbprint};
81	    retval = securityPolicy->asymmetricModule.
82	        makeCertificateThumbprint(securityPolicy, &channel->remoteCertificate,
83	                                  &remoteCertificateThumbprint);
84	
85	    return retval;
86	}
