88	static void
89	deleteMessage(UA_Message *me) {
90	    UA_ChunkPayload *cp;
91	    while((cp = SIMPLEQ_FIRST(&me->chunkPayloads))) {
92	        if(cp->copied)
93	            UA_ByteString_deleteMembers(&cp->bytes);
94	        SIMPLEQ_REMOVE_HEAD(&me->chunkPayloads, pointers);
95	        UA_free(cp);
96	    }
97	    UA_free(me);
98	}
