112	void
113	UA_SecureChannel_deleteMessages(UA_SecureChannel *channel) {
114	    UA_Message *me, *me_tmp;
115	    TAILQ_FOREACH_SAFE(me, &channel->messages, pointers, me_tmp) {
116	        TAILQ_REMOVE(&channel->messages, me, pointers);
117	        deleteMessage(me);
118	    }
119	}
