121	void
122	UA_SecureChannel_deleteMembers(UA_SecureChannel *channel) {
123	    /* Delete members */
124	    UA_ByteString_deleteMembers(&channel->remoteCertificate);
125	    UA_ByteString_deleteMembers(&channel->localNonce);
126	    UA_ByteString_deleteMembers(&channel->remoteNonce);
127	    UA_ChannelSecurityToken_deleteMembers(&channel->securityToken);
128	    UA_ChannelSecurityToken_deleteMembers(&channel->nextSecurityToken);
129	
130	    /* Delete the channel context for the security policy */
131	    if(channel->securityPolicy)
132	        channel->securityPolicy->channelModule.deleteContext(channel->channelContext);
133	
134	
135	    /* Remove the buffered messages */
136	    UA_SecureChannel_deleteMessages(channel);
137	}
