139	void
140	UA_SecureChannel_close(UA_SecureChannel *channel) {
141	    /* Set the status to closed */
142	    channel->state = UA_SECURECHANNELSTATE_CLOSED;
143	
144	    /* Detach from the connection and close the connection */
145	    if(channel->connection) {
146	        if(channel->connection->state != UA_CONNECTION_CLOSED)
147	            channel->connection->close(channel->connection);
148	        UA_Connection_detachSecureChannel(channel->connection);
149	    }
150	
151	    /* Remove session pointers (not the sessions) and NULL the pointers back to
152	     * the SecureChannel in the Session */
153	    UA_SessionHeader *sh, *temp;
154	    LIST_FOREACH_SAFE(sh, &channel->sessions, pointers, temp) {
155	        sh->channel = NULL;
156	        LIST_REMOVE(sh, pointers);
157	    }
158	}
