160	UA_StatusCode
161	UA_SecureChannel_generateLocalNonce(UA_SecureChannel *channel) {
162	    if(!channel->securityPolicy)
163	        return UA_STATUSCODE_BADINTERNALERROR;
164	
165	    /* Is the length of the previous nonce correct? */
166	    size_t nonceLength = channel->securityPolicy->symmetricModule.secureChannelNonceLength;
167	    if(channel->localNonce.length != nonceLength) {
168	        UA_ByteString_deleteMembers(&channel->localNonce);
169	        UA_StatusCode retval = UA_ByteString_allocBuffer(&channel->localNonce, nonceLength);
170	        if(retval != UA_STATUSCODE_GOOD)
171	            return retval;
172	    }
173	
174	    return channel->securityPolicy->symmetricModule.
175	        generateNonce(channel->securityPolicy, &channel->localNonce);
176	}
