178	static UA_StatusCode
179	UA_SecureChannel_generateLocalKeys(const UA_SecureChannel *const channel,
180	                                   const UA_SecurityPolicy *const securityPolicy) {
181	    UA_LOG_TRACE_CHANNEL(securityPolicy->logger, channel, "Generating new local keys");
182	    const UA_SecurityPolicyChannelModule *channelModule = &securityPolicy->channelModule;
183	    const UA_SecurityPolicySymmetricModule *symmetricModule = &securityPolicy->symmetricModule;
184	    const UA_SecurityPolicyCryptoModule *const cryptoModule = &securityPolicy->symmetricModule.cryptoModule;
185	
186	    /* Symmetric key length */
187	    size_t encryptionKeyLength =
188	        cryptoModule->encryptionAlgorithm.getLocalKeyLength(securityPolicy, channel->channelContext);
189	    size_t encryptionBlockSize =
190	        cryptoModule->encryptionAlgorithm.getLocalBlockSize(securityPolicy, channel->channelContext);
191	    size_t signingKeyLength =
192	        cryptoModule->signatureAlgorithm.getLocalKeyLength(securityPolicy, channel->channelContext);
193	    const size_t bufSize = encryptionBlockSize + signingKeyLength + encryptionKeyLength;
194	    UA_STACKARRAY(UA_Byte, bufBytes, bufSize);
195	    UA_ByteString buffer = {bufSize, bufBytes};
196	
197	    /* Local keys */
198	    UA_StatusCode retval = symmetricModule->generateKey(securityPolicy, &channel->remoteNonce,
199	                                                        &channel->localNonce, &buffer);
200	    if(retval != UA_STATUSCODE_GOOD)
201	        return retval;
202	    const UA_ByteString localSigningKey = {signingKeyLength, buffer.data};
203	    const UA_ByteString localEncryptingKey = {encryptionKeyLength,
204	                                              buffer.data + signingKeyLength};
205	    const UA_ByteString localIv = {encryptionBlockSize,
206	                                   buffer.data + signingKeyLength +
207	                                   encryptionKeyLength};
208	
209	    retval = channelModule->setLocalSymSigningKey(channel->channelContext, &localSigningKey);
210	    if(retval != UA_STATUSCODE_GOOD)
211	        return retval;
212	
213	    retval = channelModule->setLocalSymEncryptingKey(channel->channelContext, &localEncryptingKey);
214	    if(retval != UA_STATUSCODE_GOOD)
215	        return retval;
216	
217	    retval = channelModule->setLocalSymIv(channel->channelContext, &localIv);
218	    if(retval != UA_STATUSCODE_GOOD)
219	        return retval;
220	
221	    return retval;
222	}
