224	static UA_StatusCode
225	UA_SecureChannel_generateRemoteKeys(const UA_SecureChannel *const channel,
226	                                    const UA_SecurityPolicy *const securityPolicy) {
227	    UA_LOG_TRACE_CHANNEL(securityPolicy->logger, channel, "Generating new remote keys");
228	    const UA_SecurityPolicyChannelModule *channelModule = &securityPolicy->channelModule;
229	    const UA_SecurityPolicySymmetricModule *symmetricModule = &securityPolicy->symmetricModule;
230	    const UA_SecurityPolicyCryptoModule *const cryptoModule = &securityPolicy->symmetricModule.cryptoModule;
231	
232	    /* Symmetric key length */
233	    size_t encryptionKeyLength =
234	        cryptoModule->encryptionAlgorithm.getRemoteKeyLength(securityPolicy, channel->channelContext);
235	    size_t encryptionBlockSize =
236	        cryptoModule->encryptionAlgorithm.getRemoteBlockSize(securityPolicy, channel->channelContext);
237	    size_t signingKeyLength =
238	        cryptoModule->signatureAlgorithm.getRemoteKeyLength(securityPolicy, channel->channelContext);
239	    const size_t bufSize = encryptionBlockSize + signingKeyLength + encryptionKeyLength;
240	    UA_STACKARRAY(UA_Byte, bufBytes, bufSize);
241	    UA_ByteString buffer = {bufSize, bufBytes};
242	
243	    /* Remote keys */
244	    UA_StatusCode retval = symmetricModule->generateKey(securityPolicy, &channel->localNonce,
245	                                                        &channel->remoteNonce, &buffer);
246	    if(retval != UA_STATUSCODE_GOOD)
247	        return retval;
248	
249	    const UA_ByteString remoteSigningKey = {signingKeyLength, buffer.data};
250	    const UA_ByteString remoteEncryptingKey = {encryptionKeyLength,
251	                                               buffer.data + signingKeyLength};
252	    const UA_ByteString remoteIv = {encryptionBlockSize,
253	                                    buffer.data + signingKeyLength +
254	                                    encryptionKeyLength};
255	
256	    retval = channelModule->setRemoteSymSigningKey(channel->channelContext, &remoteSigningKey);
257	    if(retval != UA_STATUSCODE_GOOD)
258	        return retval;
259	
260	    retval = channelModule->setRemoteSymEncryptingKey(channel->channelContext, &remoteEncryptingKey);
261	    if(retval != UA_STATUSCODE_GOOD)
262	        return retval;
263	
264	    retval = channelModule->setRemoteSymIv(channel->channelContext, &remoteIv);
265	    if(retval != UA_STATUSCODE_GOOD)
266	        return retval;
267	
268	    return retval;
269	}
