271	UA_StatusCode
272	UA_SecureChannel_generateNewKeys(UA_SecureChannel *channel) {
273	    UA_StatusCode retval =
274	        UA_SecureChannel_generateLocalKeys(channel, channel->securityPolicy);
275	    if(retval != UA_STATUSCODE_GOOD)
276	        return retval;
277	
278	    retval = UA_SecureChannel_generateRemoteKeys(channel, channel->securityPolicy);
279	    if(retval != UA_STATUSCODE_GOOD)
280	        return retval;
281	
282	    return retval;
