296	UA_StatusCode
297	UA_SecureChannel_revolveTokens(UA_SecureChannel *channel) {
298	    if(channel->nextSecurityToken.tokenId == 0) // no security token issued
299	        return UA_STATUSCODE_BADSECURECHANNELTOKENUNKNOWN;
300	
301	    //FIXME: not thread-safe ???? Why is this not thread safe?
302	    UA_ChannelSecurityToken_deleteMembers(&channel->previousSecurityToken);
303	    UA_ChannelSecurityToken_copy(&channel->securityToken, &channel->previousSecurityToken);
304	
305	    UA_ChannelSecurityToken_deleteMembers(&channel->securityToken);
306	    UA_ChannelSecurityToken_copy(&channel->nextSecurityToken, &channel->securityToken);
307	
308	    UA_ChannelSecurityToken_deleteMembers(&channel->nextSecurityToken);
309	    UA_ChannelSecurityToken_init(&channel->nextSecurityToken);
310	
311	    /* remote keys are generated later on */
312	    return UA_SecureChannel_generateLocalKeys(channel, channel->securityPolicy);
313	}
314	/***************************/
315	/* Send Asymmetric Message */
316	/***************************/
317	
318	static UA_UInt16
319	calculatePaddingAsym(const UA_SecurityPolicy *securityPolicy, const void *channelContext,
320	                     size_t bytesToWrite, UA_Byte *paddingSize, UA_Byte *extraPaddingSize) {
321	    size_t plainTextBlockSize = securityPolicy->asymmetricModule.cryptoModule.encryptionAlgorithm.
322	        getRemotePlainTextBlockSize(securityPolicy, channelContext);
323	    size_t signatureSize = securityPolicy->asymmetricModule.cryptoModule.signatureAlgorithm.
324	        getLocalSignatureSize(securityPolicy, channelContext);
325	    size_t paddingBytes = 1;
326	    if(securityPolicy->asymmetricModule.cryptoModule.encryptionAlgorithm.
327	        getRemoteKeyLength(securityPolicy, channelContext) > 2048)
328	        ++paddingBytes;
329	    size_t padding = (plainTextBlockSize - ((bytesToWrite + signatureSize + paddingBytes) %
330	                                            plainTextBlockSize));
331	    *paddingSize = (UA_Byte)(padding & 0xff);
332	    *extraPaddingSize = (UA_Byte)(padding >> 8);
333	    return (UA_UInt16)padding;
334	}
335	
336	static size_t
337	calculateAsymAlgSecurityHeaderLength(const UA_SecureChannel *channel) {
338	    size_t asymHeaderLength = UA_ASYMMETRIC_ALG_SECURITY_HEADER_FIXED_LENGTH +
339	                              channel->securityPolicy->policyUri.length;
340	    if(channel->securityMode == UA_MESSAGESECURITYMODE_SIGN ||
341	       channel->securityMode == UA_MESSAGESECURITYMODE_SIGNANDENCRYPT) {
342	        /* OPN is always encrypted even if mode sign only */
343	        asymHeaderLength += 20; /* Thumbprints are always 20 byte long */
344	        asymHeaderLength += channel->securityPolicy->localCertificate.length;
345	    }
346	    return asymHeaderLength;
347	}
348	
349	static void
350	hideBytesAsym(const UA_SecureChannel *channel, UA_Byte **buf_start, const UA_Byte **buf_end) {
351	    const UA_SecurityPolicy *securityPolicy = channel->securityPolicy;
352	    *buf_start += UA_SECURE_CONVERSATION_MESSAGE_HEADER_LENGTH + UA_SEQUENCE_HEADER_LENGTH;
353	
354	    /* Add the SecurityHeaderLength */
355	    *buf_start += calculateAsymAlgSecurityHeaderLength(channel);
356	    size_t potentialEncryptionMaxSize = (size_t)(*buf_end - *buf_start) + UA_SEQUENCE_HEADER_LENGTH;
357	
358	    /* Hide bytes for signature and padding */
359	    if(channel->securityMode == UA_MESSAGESECURITYMODE_SIGN ||
360	       channel->securityMode == UA_MESSAGESECURITYMODE_SIGNANDENCRYPT) {
361	        *buf_end -= securityPolicy->asymmetricModule.cryptoModule.signatureAlgorithm.
362	            getLocalSignatureSize(securityPolicy, channel->channelContext);
363	        *buf_end -= 2; /* padding byte and extraPadding byte */
364	
365	        /* Add some overhead length due to RSA implementations adding a signature themselves */
366	        *buf_end -= UA_SecurityPolicy_getRemoteAsymEncryptionBufferLengthOverhead(securityPolicy,
367	                                                                                  channel->channelContext,
368	                                                                                  potentialEncryptionMaxSize);
369	    }
370	}
371	
372	static UA_StatusCode
373	padChunkAsym(UA_SecureChannel *channel, const UA_ByteString *const buf,
374	             size_t securityHeaderLength, UA_Byte **buf_pos) {
375	    const UA_SecurityPolicy *const securityPolicy = channel->securityPolicy;
376	
377	    /* Also pad if the securityMode is SIGN_ONLY, since we are using
378	     * asymmetric communication to exchange keys and thus need to encrypt. */
379	    if(channel->securityMode == UA_MESSAGESECURITYMODE_SIGN ||
380	       channel->securityMode == UA_MESSAGESECURITYMODE_SIGNANDENCRYPT) {
381	        const UA_Byte *buf_body_start =
382	            &buf->data[UA_SECURE_CONVERSATION_MESSAGE_HEADER_LENGTH +
383	                       UA_SEQUENCE_HEADER_LENGTH + securityHeaderLength];
384	        const size_t bytesToWrite =
385	            (uintptr_t)*buf_pos - (uintptr_t)buf_body_start + UA_SEQUENCE_HEADER_LENGTH;
386	        UA_Byte paddingSize = 0;
387	        UA_Byte extraPaddingSize = 0;
388	        UA_UInt16 totalPaddingSize =
389	            calculatePaddingAsym(securityPolicy, channel->channelContext,
390	                                 bytesToWrite, &paddingSize, &extraPaddingSize);
391	
392	        // This is <= because the paddingSize byte also has to be written.
393	        for(UA_UInt16 i = 0; i <= totalPaddingSize; ++i) {
394	            **buf_pos = paddingSize;
395	            ++*buf_pos;
396	        }
397	        if(securityPolicy->asymmetricModule.cryptoModule.encryptionAlgorithm.
398	            getRemoteKeyLength(securityPolicy, channel->channelContext) > 2048) {
399	            **buf_pos = extraPaddingSize;
400	            ++*buf_pos;
401	        }
402	    }
403	
404	    return UA_STATUSCODE_GOOD;
405	}
406	
407	static UA_StatusCode
408	prependHeadersAsym(UA_SecureChannel *const channel, UA_Byte *header_pos,
409	                   const UA_Byte *buf_end, size_t totalLength,
410	                   size_t securityHeaderLength, UA_UInt32 requestId,
411	                   size_t *const finalLength) {
412	    UA_StatusCode retval;
413	    size_t dataToEncryptLength =
414	        totalLength - (UA_SECURE_CONVERSATION_MESSAGE_HEADER_LENGTH + securityHeaderLength);
415	    UA_SecureConversationMessageHeader respHeader;
416	    respHeader.messageHeader.messageTypeAndChunkType = UA_MESSAGETYPE_OPN + UA_CHUNKTYPE_FINAL;
417	    respHeader.messageHeader.messageSize = (UA_UInt32)
418	        (totalLength + UA_SecurityPolicy_getRemoteAsymEncryptionBufferLengthOverhead(channel->securityPolicy,
419	                                                                                     channel->channelContext,
420	                                                                                     dataToEncryptLength));
421	    respHeader.secureChannelId = channel->securityToken.channelId;
422	    retval = UA_encodeBinary(&respHeader, &UA_TRANSPORT[UA_TRANSPORT_SECURECONVERSATIONMESSAGEHEADER],
423	                             &header_pos, &buf_end, NULL, NULL);
424	    if(retval != UA_STATUSCODE_GOOD)
425	        return retval;
426	
427	    UA_AsymmetricAlgorithmSecurityHeader asymHeader;
428	    UA_AsymmetricAlgorithmSecurityHeader_init(&asymHeader);
429	    asymHeader.securityPolicyUri = channel->securityPolicy->policyUri;
430	    if(channel->securityMode == UA_MESSAGESECURITYMODE_SIGN ||
431	       channel->securityMode == UA_MESSAGESECURITYMODE_SIGNANDENCRYPT) {
432	        asymHeader.senderCertificate = channel->securityPolicy->localCertificate;
433	        asymHeader.receiverCertificateThumbprint.length = 20;
434	        asymHeader.receiverCertificateThumbprint.data = channel->remoteCertificateThumbprint;
435	    }
436	    retval = UA_encodeBinary(&asymHeader, &UA_TRANSPORT[UA_TRANSPORT_ASYMMETRICALGORITHMSECURITYHEADER],
437	                             &header_pos, &buf_end, NULL, NULL);
438	    if(retval != UA_STATUSCODE_GOOD)
439	        return retval;
440	
441	    UA_SequenceHeader seqHeader;
442	    seqHeader.requestId = requestId;
443	    seqHeader.sequenceNumber = UA_atomic_addUInt32(&channel->sendSequenceNumber, 1);
444	    retval = UA_encodeBinary(&seqHeader, &UA_TRANSPORT[UA_TRANSPORT_SEQUENCEHEADER],
445	                             &header_pos, &buf_end, NULL, NULL);
446	
447	    *finalLength = respHeader.messageHeader.messageSize;
448	
449	    return retval;
450	}
