452	static UA_StatusCode
453	signAndEncryptAsym(UA_SecureChannel *const channel, size_t preSignLength,
454	                   UA_ByteString *buf, size_t securityHeaderLength,
455	                   size_t totalLength) {
456	    const UA_SecurityPolicy *const securityPolicy = channel->securityPolicy;
457	    UA_StatusCode retval = UA_STATUSCODE_GOOD;
458	
459	    if(channel->securityMode == UA_MESSAGESECURITYMODE_SIGN ||
460	       channel->securityMode == UA_MESSAGESECURITYMODE_SIGNANDENCRYPT) {
461	        /* Sign message */
462	        const UA_ByteString dataToSign = {preSignLength, buf->data};
463	        size_t sigsize = securityPolicy->asymmetricModule.cryptoModule.signatureAlgorithm.
464	            getLocalSignatureSize(securityPolicy, channel->channelContext);
465	        UA_ByteString signature = {sigsize, buf->data + preSignLength};
466	        retval = securityPolicy->asymmetricModule.cryptoModule.signatureAlgorithm.
467	            sign(securityPolicy, channel->channelContext, &dataToSign, &signature);
468	        if(retval != UA_STATUSCODE_GOOD)
469	            return retval;
470	
471	        /* Specification part 6, 6.7.4: The OpenSecureChannel Messages are
472	         * signed and encrypted if the SecurityMode is not None (even if the
473	         * SecurityMode is SignOnly). */
474	        size_t unencrypted_length =
475	            UA_SECURE_CONVERSATION_MESSAGE_HEADER_LENGTH + securityHeaderLength;
476	        UA_ByteString dataToEncrypt = {totalLength - unencrypted_length,
477	                                       &buf->data[unencrypted_length]};
478	        retval = securityPolicy->asymmetricModule.cryptoModule.encryptionAlgorithm.
479	            encrypt(securityPolicy, channel->channelContext, &dataToEncrypt);
480	        if(retval != UA_STATUSCODE_GOOD)
481	            return retval;
482	    }
483	
484	    return retval;
485	}
