487	/* Sends an OPN message using asymmetric encryption if defined */
488	UA_StatusCode
489	UA_SecureChannel_sendAsymmetricOPNMessage(UA_SecureChannel *channel, UA_UInt32 requestId,
490	                                          const void *content, const UA_DataType *contentType) {
491	    if(channel->securityMode == UA_MESSAGESECURITYMODE_INVALID)
492	        return UA_STATUSCODE_BADSECURITYMODEREJECTED;
493	
494	    const UA_SecurityPolicy *const securityPolicy = channel->securityPolicy;
495	    UA_Connection *connection = channel->connection;
496	    if(!connection)
497	        return UA_STATUSCODE_BADINTERNALERROR;
498	
499	    /* Allocate the message buffer */
500	    UA_ByteString buf = UA_BYTESTRING_NULL;
501	    UA_StatusCode retval =
502	        connection->getSendBuffer(connection, connection->config.sendBufferSize, &buf);
503	    if(retval != UA_STATUSCODE_GOOD)
504	        goto error;
505	
506	    /* Restrict buffer to the available space for the payload */
507	    UA_Byte *buf_pos = buf.data;
508	    const UA_Byte *buf_end = &buf.data[buf.length];
509	    hideBytesAsym(channel, &buf_pos, &buf_end);
510	
511	    /* Encode the message type and content */
512	    UA_NodeId typeId = UA_NODEID_NUMERIC(0, contentType->binaryEncodingId);
513	    retval = UA_encodeBinary(&typeId, &UA_TYPES[UA_TYPES_NODEID], &buf_pos, &buf_end, NULL, NULL);
514	    if(retval != UA_STATUSCODE_GOOD)
515	        goto error;
516	
517	    retval = UA_encodeBinary(content, contentType, &buf_pos, &buf_end, NULL, NULL);
518	    if(retval != UA_STATUSCODE_GOOD)
519	        goto error;
520	
521	    const size_t securityHeaderLength = calculateAsymAlgSecurityHeaderLength(channel);
522	
523	    retval = padChunkAsym(channel, &buf, securityHeaderLength, &buf_pos);
524	    if(retval != UA_STATUSCODE_GOOD)
525	        goto error;
526	
527	    /* The total message length */
528	    size_t pre_sig_length = (uintptr_t)buf_pos - (uintptr_t)buf.data;
529	    size_t total_length = pre_sig_length;
530	    if(channel->securityMode == UA_MESSAGESECURITYMODE_SIGN ||
531	       channel->securityMode == UA_MESSAGESECURITYMODE_SIGNANDENCRYPT)
532	        total_length += securityPolicy->asymmetricModule.cryptoModule.signatureAlgorithm.
533	            getLocalSignatureSize(securityPolicy, channel->channelContext);
534	
535	    /* The total message length is known here which is why we */
536	    /* encode the headers at this step and not earlier. */
537	    size_t finalLength = 0;
538	    retval = prependHeadersAsym(channel, buf.data, buf_end, total_length,
539	                                securityHeaderLength, requestId, &finalLength);
540	    if(retval != UA_STATUSCODE_GOOD)
541	        goto error;
542	
543	    retval = signAndEncryptAsym(channel, pre_sig_length, &buf, securityHeaderLength, total_length);
544	    if(retval != UA_STATUSCODE_GOOD)
545	        goto error;
546	
547	    /* Send the message, the buffer is freed in the network layer */
548	    buf.length = finalLength;
549	    retval = connection->send(connection, &buf);
550	#ifdef UA_ENABLE_UNIT_TEST_FAILURE_HOOKS
551	    retval |= sendAsym_sendFailure
552	#endif
553	    return retval;
554	
555	error:
556	    connection->releaseSendBuffer(connection, &buf);
557	    return retval;
558	}
559	
560	/**************************/
561	/* Send Symmetric Message */
562	/**************************/
563	
564	static UA_UInt16
565	calculatePaddingSym(const UA_SecurityPolicy *securityPolicy, const void *channelContext,
566	                    size_t bytesToWrite, UA_Byte *paddingSize, UA_Byte *extraPaddingSize) {
567	    size_t encryptionBlockSize = securityPolicy->symmetricModule.cryptoModule.encryptionAlgorithm.
568	        getLocalBlockSize(securityPolicy, channelContext);
569	    size_t signatureSize = securityPolicy->symmetricModule.cryptoModule.signatureAlgorithm.
570	        getLocalSignatureSize(securityPolicy, channelContext);
571	
572	    UA_UInt16 padding = (UA_UInt16)(encryptionBlockSize - ((bytesToWrite + signatureSize + 1) % encryptionBlockSize));
573	    *paddingSize = (UA_Byte)padding;
574	    *extraPaddingSize = (UA_Byte)(padding >> 8);
575	    return padding;
576	}
577	
578	static void
579	setBufPos(UA_MessageContext *mc) {
580	    const UA_SecureChannel *channel = mc->channel;
581	    const UA_SecurityPolicy *securityPolicy = channel->securityPolicy;
582	
583	    /* Forward the data pointer so that the payload is encoded after the
584	     * message header */
585	    mc->buf_pos = &mc->messageBuffer.data[UA_SECURE_MESSAGE_HEADER_LENGTH];
586	    mc->buf_end = &mc->messageBuffer.data[mc->messageBuffer.length];
587	
588	    /* Reserve space for the message footer at the end of the chunk if the chunk
589	     * is signed and/or encrypted. The footer includes the fields PaddingSize,
590	     * Padding, ExtraPadding and Signature. The padding fields are only present
591	     * if the chunk is encrypted. */
592	    if(channel->securityMode == UA_MESSAGESECURITYMODE_SIGN ||
593	       channel->securityMode == UA_MESSAGESECURITYMODE_SIGNANDENCRYPT)
594	        mc->buf_end -= securityPolicy->symmetricModule.cryptoModule.signatureAlgorithm.
595	            getLocalSignatureSize(securityPolicy, channel->channelContext);
596	
597	    /* The size of the padding depends on the amount of data that shall be sent
598	     * and is unknown at this point. Reserve space for the PaddingSize byte,
599	     * the maximum amount of Padding which equals the block size of the
600	     * symmetric encryption algorithm and last 1 byte for the ExtraPaddingSize
601	     * field that is present if the encryption key is larger than 2048 bits.
602	     * The actual padding size is later calculated by the function
603	     * calculatePaddingSym(). */
604	    if(channel->securityMode == UA_MESSAGESECURITYMODE_SIGNANDENCRYPT)
605	    {
606	        /* PaddingSize and ExtraPaddingSize fields */
607	        size_t encryptionBlockSize = securityPolicy->symmetricModule.cryptoModule.encryptionAlgorithm.
608	            getLocalBlockSize(securityPolicy, channel->channelContext );
609	        mc->buf_end -= 1 + ((encryptionBlockSize >> 8) ? 1 : 0);
610	
611	        /* Reduce the message body size with the remainder of the operation
612	         * maxEncryptedDataSize modulo EncryptionBlockSize to get a whole
613	         * number of blocks to encrypt later. Also reserve one byte for
614	         * padding (1 <= paddingSize <= encryptionBlockSize).
615	         */
616	        size_t maxEncryptDataSize = mc->messageBuffer.length -
617	            UA_SECURE_CONVERSATION_MESSAGE_HEADER_LENGTH -
618	            UA_SYMMETRIC_ALG_SECURITY_HEADER_LENGTH;
619	        mc->buf_end -= (maxEncryptDataSize % encryptionBlockSize) + 1;
620	    }
621	}
622	
623	static UA_StatusCode
624	checkLimitsSym(UA_MessageContext *const messageContext, size_t *const bodyLength) {
625	    /* Will this chunk surpass the capacity of the SecureChannel for the message? */
626	    UA_Connection *const connection = messageContext->channel->connection;
627	    if(!connection)
628	        return UA_STATUSCODE_BADINTERNALERROR;
629	
630	    UA_Byte *buf_body_start = messageContext->messageBuffer.data + UA_SECURE_MESSAGE_HEADER_LENGTH;
631	    const UA_Byte *buf_body_end = messageContext->buf_pos;
632	    *bodyLength = (uintptr_t)buf_body_end - (uintptr_t)buf_body_start;
633	    messageContext->messageSizeSoFar += *bodyLength;
634	    messageContext->chunksSoFar++;
635	
636	    if(messageContext->messageSizeSoFar > connection->config.maxMessageSize &&
637	       connection->config.maxMessageSize != 0)
638	        return UA_STATUSCODE_BADRESPONSETOOLARGE;
639	
640	    if(messageContext->chunksSoFar > connection->config.maxChunkCount &&
641	       connection->config.maxChunkCount != 0)
642	        return UA_STATUSCODE_BADRESPONSETOOLARGE;
643	
644	    return UA_STATUSCODE_GOOD;
645	}
646	
647	static UA_StatusCode
648	padChunkSym(UA_MessageContext *messageContext, size_t bodyLength) {
649	    /* The bytes for the padding and signature were removed
650	     * from buf_end before encoding the payload. So we don't check here. */
651	    if(messageContext->channel->securityMode == UA_MESSAGESECURITYMODE_SIGNANDENCRYPT) {
652	        size_t bytesToWrite = bodyLength + UA_SEQUENCE_HEADER_LENGTH;
653	        UA_Byte paddingSize = 0;
654	        UA_Byte extraPaddingSize = 0;
655	        UA_UInt16 totalPaddingSize =
656	            calculatePaddingSym(messageContext->channel->securityPolicy,
657	                                messageContext->channel->channelContext,
658	                                bytesToWrite, &paddingSize, &extraPaddingSize);
659	
660	        // This is <= because the paddingSize byte also has to be written.
661	        for(UA_UInt16 i = 0; i <= totalPaddingSize; ++i) {
662	            *messageContext->buf_pos = paddingSize;
663	            ++(messageContext->buf_pos);
664	        }
665	        if(extraPaddingSize > 0) {
666	            *messageContext->buf_pos = extraPaddingSize;
667	            ++(messageContext->buf_pos);
668	        }
669	    }
670	
671	    return UA_STATUSCODE_GOOD;
672	}
673	
674	static UA_StatusCode
675	encodeHeadersSym(UA_MessageContext *const messageContext, size_t totalLength) {
676	    UA_StatusCode res = UA_STATUSCODE_GOOD;
677	    UA_SecureChannel *const channel = messageContext->channel;
678	    UA_Byte *header_pos = messageContext->messageBuffer.data;
679	    UA_SecureConversationMessageHeader respHeader;
680	    respHeader.secureChannelId = channel->securityToken.channelId;
681	    respHeader.messageHeader.messageTypeAndChunkType = messageContext->messageType;
682	    respHeader.messageHeader.messageSize = (UA_UInt32)totalLength;
683	    if(messageContext->final)
684	        respHeader.messageHeader.messageTypeAndChunkType += UA_CHUNKTYPE_FINAL;
685	    else
686	        respHeader.messageHeader.messageTypeAndChunkType += UA_CHUNKTYPE_INTERMEDIATE;
687	    res = UA_encodeBinary(&respHeader, &UA_TRANSPORT[UA_TRANSPORT_SECURECONVERSATIONMESSAGEHEADER],
688	                          &header_pos, &messageContext->buf_end, NULL, NULL);
689	
690	    UA_SymmetricAlgorithmSecurityHeader symSecHeader;
691	    symSecHeader.tokenId = channel->securityToken.tokenId;
692	    res |= UA_encodeBinary(&symSecHeader.tokenId,
693	                           &UA_TRANSPORT[UA_TRANSPORT_SYMMETRICALGORITHMSECURITYHEADER],
694	                           &header_pos, &messageContext->buf_end, NULL, NULL);
695	
696	    UA_SequenceHeader seqHeader;
697	    seqHeader.requestId = messageContext->requestId;
698	    seqHeader.sequenceNumber = UA_atomic_addUInt32(&channel->sendSequenceNumber, 1);
699	    res |= UA_encodeBinary(&seqHeader, &UA_TRANSPORT[UA_TRANSPORT_SEQUENCEHEADER],
700	                           &header_pos, &messageContext->buf_end, NULL, NULL);
701	
702	    return res;
703	}
704	
705	static UA_StatusCode
706	signChunkSym(UA_MessageContext *const messageContext, size_t preSigLength) {
707	    UA_SecureChannel *const channel = messageContext->channel;
708	    const UA_SecurityPolicy *const securityPolicy = channel->securityPolicy;
709	    if(channel->securityMode == UA_MESSAGESECURITYMODE_SIGN ||
710	       channel->securityMode == UA_MESSAGESECURITYMODE_SIGNANDENCRYPT) {
711	        UA_ByteString dataToSign = messageContext->messageBuffer;
712	        dataToSign.length = preSigLength;
713	        UA_ByteString signature;
714	        signature.length = securityPolicy->symmetricModule.cryptoModule.signatureAlgorithm.
715	            getLocalSignatureSize(securityPolicy, channel->channelContext);
716	        signature.data = messageContext->buf_pos;
717	        return securityPolicy->symmetricModule.cryptoModule.signatureAlgorithm
718	                             .sign(securityPolicy, channel->channelContext, &dataToSign, &signature);
719	    }
720	
721	    return UA_STATUSCODE_GOOD;
722	}
723	
724	static UA_StatusCode
725	encryptChunkSym(UA_MessageContext *const messageContext, size_t totalLength) {
726	    UA_SecureChannel *const channel = messageContext->channel;
727	    const UA_SecurityPolicy *const securityPolicy = channel->securityPolicy;
728	    if(channel->securityMode == UA_MESSAGESECURITYMODE_SIGNANDENCRYPT) {
729	        UA_ByteString dataToEncrypt;
730	        dataToEncrypt.data = messageContext->messageBuffer.data + UA_SECUREMH_AND_SYMALGH_LENGTH;
731	        dataToEncrypt.length = totalLength - UA_SECUREMH_AND_SYMALGH_LENGTH;
732	        return securityPolicy->symmetricModule.cryptoModule.encryptionAlgorithm.
733	            encrypt(securityPolicy, channel->channelContext, &dataToEncrypt);
734	    }
735	
736	    return UA_STATUSCODE_GOOD;
737	}
738	
739	static UA_StatusCode
740	sendSymmetricChunk(UA_MessageContext *messageContext) {
741	    UA_StatusCode res = UA_STATUSCODE_GOOD;
742	    UA_SecureChannel *const channel = messageContext->channel;
743	    const UA_SecurityPolicy *securityPolicy = channel->securityPolicy;
744	    UA_Connection *const connection = channel->connection;
745	    if(!connection)
746	        return UA_STATUSCODE_BADINTERNALERROR;
747	
748	    size_t bodyLength = 0;
749	    res = checkLimitsSym(messageContext, &bodyLength);
750	    if(res != UA_STATUSCODE_GOOD)
751	        goto error;
752	
753	    res = padChunkSym(messageContext, bodyLength);
754	    if(res != UA_STATUSCODE_GOOD)
755	        goto error;
756	
757	    /* The total message length */
758	    size_t pre_sig_length = (uintptr_t)(messageContext->buf_pos) - (uintptr_t)messageContext->messageBuffer.data;
759	    size_t total_length = pre_sig_length;
760	    if(channel->securityMode == UA_MESSAGESECURITYMODE_SIGN ||
761	       channel->securityMode == UA_MESSAGESECURITYMODE_SIGNANDENCRYPT)
762	        total_length += securityPolicy->symmetricModule.cryptoModule.signatureAlgorithm.
763	            getLocalSignatureSize(securityPolicy, channel->channelContext);
764	    /* Space for the padding and the signature have been reserved in setBufPos() */
765	    UA_assert(total_length <= connection->config.sendBufferSize);
766	    messageContext->messageBuffer.length = total_length; /* For giving the buffer to the network layer */
767	
768	    UA_assert(res == UA_STATUSCODE_GOOD);
769	    res = encodeHeadersSym(messageContext, total_length);
770	    if(res != UA_STATUSCODE_GOOD)
771	        goto error;
772	
773	    res = signChunkSym(messageContext, pre_sig_length);
774	    if(res != UA_STATUSCODE_GOOD)
775	        goto error;
776	
777	    res = encryptChunkSym(messageContext, total_length);
778	    if(res != UA_STATUSCODE_GOOD)
779	        goto error;
780	
781	    /* Send the chunk, the buffer is freed in the network layer */
782	    return connection->send(channel->connection, &messageContext->messageBuffer);
783	
784	error:
785	    connection->releaseSendBuffer(channel->connection, &messageContext->messageBuffer);
786	    return res;
787	}
788	
789	/* Callback from the encoding layer. Send the chunk and replace the buffer. */
790	static UA_StatusCode
791	sendSymmetricEncodingCallback(void *data, UA_Byte **buf_pos, const UA_Byte **buf_end) {
792	    /* Set buf values from encoding in the messagecontext */
793	    UA_MessageContext *mc = (UA_MessageContext *)data;
794	    mc->buf_pos = *buf_pos;
795	    mc->buf_end = *buf_end;
796	
797	    /* Send out */
798	    UA_StatusCode retval = sendSymmetricChunk(mc);
799	    if(retval != UA_STATUSCODE_GOOD)
800	        return retval;
801	
802	    /* Set a new buffer for the next chunk */
803	    UA_Connection *connection = mc->channel->connection;
804	    if(!connection)
805	        return UA_STATUSCODE_BADINTERNALERROR;
806	
807	    retval = connection->getSendBuffer(connection, connection->config.sendBufferSize,
808	                                       &mc->messageBuffer);
809	    if(retval != UA_STATUSCODE_GOOD)
810	        return retval;
811	
812	    /* Hide bytes for header, padding and signature */
813	    setBufPos(mc);
814	    *buf_pos = mc->buf_pos;
815	    *buf_end = mc->buf_end;
816	    return UA_STATUSCODE_GOOD;
817	}
818	
819	UA_StatusCode
820	UA_MessageContext_begin(UA_MessageContext *mc, UA_SecureChannel *channel,
821	                        UA_UInt32 requestId, UA_MessageType messageType) {
822	    UA_Connection *connection = channel->connection;
823	    if(!connection)
824	        return UA_STATUSCODE_BADINTERNALERROR;
825	
826	    if(messageType != UA_MESSAGETYPE_MSG && messageType != UA_MESSAGETYPE_CLO)
827	        return UA_STATUSCODE_BADINTERNALERROR;
828	
829	    /* Create the chunking info structure */
830	    mc->channel = channel;
831	    mc->requestId = requestId;
832	    mc->chunksSoFar = 0;
833	    mc->messageSizeSoFar = 0;
834	    mc->final = false;
835	    mc->messageBuffer = UA_BYTESTRING_NULL;
836	    mc->messageType = messageType;
837	
838	    /* Allocate the message buffer */
839	    UA_StatusCode retval =
840	        connection->getSendBuffer(connection, connection->config.sendBufferSize,
841	                                  &mc->messageBuffer);
842	    if(retval != UA_STATUSCODE_GOOD)
843	        return retval;
844	
845	    /* Hide bytes for header, padding and signature */
846	    setBufPos(mc);
847	    return UA_STATUSCODE_GOOD;
848	}
849	
850	UA_StatusCode
851	UA_MessageContext_encode(UA_MessageContext *mc, const void *content,
852	                         const UA_DataType *contentType) {
853	    UA_StatusCode retval = UA_encodeBinary(content, contentType, &mc->buf_pos, &mc->buf_end,
854	                                           sendSymmetricEncodingCallback, mc);
855	    if(retval != UA_STATUSCODE_GOOD) {
856	        /* TODO: Send the abort message */
857	        if(mc->messageBuffer.length > 0) {
858	            UA_Connection *connection = mc->channel->connection;
859	            connection->releaseSendBuffer(connection, &mc->messageBuffer);
860	        }
861	    }
862	    return retval;
863	}
864	
865	UA_StatusCode
866	UA_MessageContext_finish(UA_MessageContext *mc) {
867	    mc->final = true;
868	    return sendSymmetricChunk(mc);
869	}
870	
871	void
872	UA_MessageContext_abort(UA_MessageContext *mc) {
873	    UA_Connection *connection = mc->channel->connection;
874	    connection->releaseSendBuffer(connection, &mc->messageBuffer);
875	}
876	
877	UA_StatusCode
878	UA_SecureChannel_sendSymmetricMessage(UA_SecureChannel *channel, UA_UInt32 requestId,
879	                                      UA_MessageType messageType, void *payload,
880	                                      const UA_DataType *payloadType) {
881	    if(!channel || !channel->connection || !payload || !payloadType)
882	        return UA_STATUSCODE_BADINTERNALERROR;
883	
884	    if(channel->connection->state == UA_CONNECTION_CLOSED)
885	        return UA_STATUSCODE_BADCONNECTIONCLOSED;
886	
887	    UA_MessageContext mc;
888	    UA_StatusCode retval = UA_MessageContext_begin(&mc, channel, requestId, messageType);
889	    if(retval != UA_STATUSCODE_GOOD)
890	        return retval;
891	
892	    /* Assert's required for clang-analyzer */
893	    UA_assert(mc.buf_pos == &mc.messageBuffer.data[UA_SECURE_MESSAGE_HEADER_LENGTH]);
894	    UA_assert(mc.buf_end <= &mc.messageBuffer.data[mc.messageBuffer.length]);
895	
896	    UA_NodeId typeId = UA_NODEID_NUMERIC(0, payloadType->binaryEncodingId);
897	    retval = UA_MessageContext_encode(&mc, &typeId, &UA_TYPES[UA_TYPES_NODEID]);
898	    if(retval != UA_STATUSCODE_GOOD)
899	        return retval;
900	
901	    retval = UA_MessageContext_encode(&mc, payload, payloadType);
902	    if(retval != UA_STATUSCODE_GOOD)
903	        return retval;
904	
905	    return UA_MessageContext_finish(&mc);
906	}
