908	/*****************************/
909	/* Assemble Complete Message */
910	/*****************************/
911	
912	static UA_StatusCode
913	addChunkPayload(UA_SecureChannel *channel, UA_UInt32 requestId,
914	                UA_MessageType messageType, UA_ByteString *chunkPayload,
915	                UA_Boolean final) {
916	    UA_Message *latest = TAILQ_LAST(&channel->messages, UA_MessageQueue);
917	    if(latest) {
918	        if(latest->requestId != requestId) {
919	            /* Start of a new message */
920	            if(!latest->final)
921	                return UA_STATUSCODE_BADTCPMESSAGETYPEINVALID;
922	            latest = NULL;
923	        } else {
924	            if(latest->messageType != messageType) /* MessageType mismatch */
925	                return UA_STATUSCODE_BADTCPMESSAGETYPEINVALID;
926	            if(latest->final) /* Correct message, but already finalized */
927	                return UA_STATUSCODE_BADTCPMESSAGETYPEINVALID;
928	        }
929	    }
930	
931	    /* Create a new message entry */
932	    if(!latest) {
933	        latest = (UA_Message *)UA_malloc(sizeof(UA_Message));
934	        if(!latest)
935	            return UA_STATUSCODE_BADOUTOFMEMORY;
936	        memset(latest, 0, sizeof(UA_Message));
937	        latest->requestId = requestId;
938	        latest->messageType = messageType;
939	        SIMPLEQ_INIT(&latest->chunkPayloads);
940	        TAILQ_INSERT_TAIL(&channel->messages, latest, pointers);
941	    }
942	
943	    /* Test against the connection settings */
944	    const UA_ConnectionConfig *config = &channel->connection->config;
945	    UA_assert(config != NULL); /* clang-analyzer false positive */
946	    if(config->maxChunkCount > 0 &&
947	       config->maxChunkCount <= latest->chunkPayloadsSize)
948	        return UA_STATUSCODE_BADRESPONSETOOLARGE;
949	    if(config->maxMessageSize > 0 && config->maxMessageSize < latest->messageSize + chunkPayload->length)
950	        return UA_STATUSCODE_BADRESPONSETOOLARGE;
951	
952	    /* Create a new chunk entry */
953	    UA_ChunkPayload *cp = (UA_ChunkPayload *)UA_malloc(sizeof(UA_ChunkPayload));
954	    if(!cp)
955	        return UA_STATUSCODE_BADOUTOFMEMORY;
956	    cp->bytes = *chunkPayload;
957	    cp->copied = false;
958	
959	    /* Add the chunk */
960	    SIMPLEQ_INSERT_TAIL(&latest->chunkPayloads, cp, pointers);
961	    latest->chunkPayloadsSize += 1;
962	    latest->messageSize += chunkPayload->length;
963	    latest->final = final;
964	
965	    return UA_STATUSCODE_GOOD;
966	}
967	
968	static UA_StatusCode
969	processMessage(UA_SecureChannel *channel, const UA_Message *message,
970	               void *application, UA_ProcessMessageCallback callback) {
971	    if(message->chunkPayloadsSize == 1) {
972	        /* No need to combine chunks */
973	        UA_ChunkPayload *cp = SIMPLEQ_FIRST(&message->chunkPayloads);
974	        callback(application, channel, message->messageType, message->requestId, &cp->bytes);
975	    } else {
976	        /* Allocate memory */
977	        UA_ByteString bytes;
978	        bytes.data = (UA_Byte *)UA_malloc(message->messageSize);
979	        if(!bytes.data) {
980	            UA_LOG_ERROR(channel->securityPolicy->logger, UA_LOGCATEGORY_SECURECHANNEL,
981	                         "Could not allocate the memory to assemble the message");
982	            return UA_STATUSCODE_BADOUTOFMEMORY;
983	        }
984	        bytes.length = message->messageSize;
985	
986	        /* Assemble the full message */
987	        size_t curPos = 0;
988	        UA_ChunkPayload *cp;
989	        SIMPLEQ_FOREACH(cp, &message->chunkPayloads, pointers) {
990	            memcpy(&bytes.data[curPos], cp->bytes.data, cp->bytes.length);
991	            curPos += cp->bytes.length;
992	        }
993	
994	        /* Process the message */
995	        callback(application, channel, message->messageType, message->requestId, &bytes);
996	        UA_ByteString_deleteMembers(&bytes);
997	    }
998	    return UA_STATUSCODE_GOOD;
999	}
1000	
1001	UA_StatusCode
1002	UA_SecureChannel_processCompleteMessages(UA_SecureChannel *channel, void *application,
1003	                                         UA_ProcessMessageCallback callback) {
1004	    UA_Message *message, *tmp_message;
1005	    UA_StatusCode retval = UA_STATUSCODE_GOOD;
1006	    TAILQ_FOREACH_SAFE(message, &channel->messages, pointers, tmp_message) {
1007	        /* Stop at the first incomplete message */
1008	        if(!message->final)
1009	            break;
1010	
1011	        /* Has the channel been closed (during the last message)? */
1012	        if(channel->state == UA_SECURECHANNELSTATE_CLOSED)
1013	            break;
1014	
1015	        /* Remove the current message before processing */
1016	        TAILQ_REMOVE(&channel->messages, message, pointers);
1017	
1018	        /* Process */
1019	        retval = processMessage(channel, message, application, callback);
1020	        if(retval != UA_STATUSCODE_GOOD)
1021	            break;
1022	
1023	        /* Clean up the message */
1024	        UA_ChunkPayload *payload;
1025	        while((payload = SIMPLEQ_FIRST(&message->chunkPayloads))) {
1026	            if(payload->copied)
1027	                UA_ByteString_deleteMembers(&payload->bytes);
1028	            SIMPLEQ_REMOVE_HEAD(&message->chunkPayloads, pointers);
1029	            UA_free(payload);
1030	        }
1031	        UA_free(message);
1032	    }
1033	    return retval;
1034	}
1035	
1036	/****************************/
1037	/* Process a received Chunk */
1038	/****************************/
1039	
1040	static UA_StatusCode
1041	decryptChunk(const UA_SecureChannel *const channel,
1042	             const UA_SecurityPolicyCryptoModule *const cryptoModule,
1043	             UA_MessageType const messageType, const UA_ByteString *const chunk,
1044	             size_t const offset, size_t *const chunkSizeAfterDecryption) {
1045	    UA_LOG_TRACE_CHANNEL(channel->securityPolicy->logger, channel, "Decrypting chunk");
1046	
1047	    UA_ByteString cipherText = {chunk->length - offset, chunk->data + offset};
1048	    size_t sizeBeforeDecryption = cipherText.length;
1049	    size_t chunkSizeBeforeDecryption = *chunkSizeAfterDecryption;
1050	
1051	    /* Always decrypt opn messages if mode not none */
1052	    if(channel->securityMode == UA_MESSAGESECURITYMODE_SIGNANDENCRYPT ||
1053	       messageType == UA_MESSAGETYPE_OPN) {
1054	        UA_StatusCode retval = cryptoModule->encryptionAlgorithm
1055	                                           .decrypt(channel->securityPolicy, channel->channelContext, &cipherText);
1056	        *chunkSizeAfterDecryption -= (sizeBeforeDecryption - cipherText.length);
1057	        if(retval != UA_STATUSCODE_GOOD) {
1058	            return retval;
1059	        }
1060	    }
1061	
1062	    UA_LOG_TRACE_CHANNEL(channel->securityPolicy->logger, channel,
1063	                         "Chunk size before and after decryption: %lu, %lu",
1064	                         (long unsigned int)chunkSizeBeforeDecryption, (long unsigned int)*chunkSizeAfterDecryption);
1065	
1066	    return UA_STATUSCODE_GOOD;
1067	}
1068	
1069	static UA_StatusCode
1070	getPaddingSize(const UA_SecureChannel *const channel,
1071	               const UA_SecurityPolicyCryptoModule *const cryptoModule,
1072	               UA_MessageType const messageType, const UA_ByteString *const chunk,
1073	               size_t const chunkSizeAfterDecryption, size_t sigsize, size_t *const paddingSize) {
1074	    if(channel->securityMode == UA_MESSAGESECURITYMODE_SIGNANDENCRYPT ||
1075	       (messageType == UA_MESSAGETYPE_OPN &&
1076	        channel->securityMode > UA_MESSAGESECURITYMODE_NONE)) {
1077	        *paddingSize = (size_t)chunk->data[chunkSizeAfterDecryption - sigsize - 1];
1078	
1079	        size_t keyLength =
1080	            cryptoModule->encryptionAlgorithm.getRemoteKeyLength(channel->securityPolicy, channel->channelContext);
1081	        if(keyLength > 2048) {
1082	            *paddingSize <<= 8; /* Extra padding size */
1083	            *paddingSize += chunk->data[chunkSizeAfterDecryption - sigsize - 2];
1084	            // see comment below but for extraPaddingSize
1085	            *paddingSize += 1;
1086	        }
1087	
1088	        // we need to add one to the padding size since the paddingSize byte itself need to be removed as well.
1089	        // TODO: write unit test for correct padding calculation
1090	        *paddingSize += 1;
1091	    }
1092	    UA_LOG_TRACE_CHANNEL(channel->securityPolicy->logger, channel,
1093	                         "Calculated padding size to be %lu",
1094	                         (long unsigned int)*paddingSize);
1095	
1096	    return UA_STATUSCODE_GOOD;
1097	}
1098	
1099	static UA_StatusCode
1100	verifyChunk(const UA_SecureChannel *const channel,
1101	            const UA_SecurityPolicyCryptoModule *const cryptoModule,
1102	            const UA_ByteString *const chunk,
1103	            size_t const chunkSizeAfterDecryption, size_t sigsize) {
1104	    UA_LOG_TRACE_CHANNEL(channel->securityPolicy->logger, channel, "Verifying chunk signature");
1105	    /* Verify the signature */
1106	    const UA_ByteString chunkDataToVerify = {chunkSizeAfterDecryption - sigsize, chunk->data};
1107	    const UA_ByteString signature = {sigsize, chunk->data + chunkSizeAfterDecryption - sigsize};
1108	    UA_StatusCode retval = cryptoModule->signatureAlgorithm.verify(channel->securityPolicy, channel->channelContext,
1109	                                                                   &chunkDataToVerify, &signature);
1110	#ifdef UA_ENABLE_UNIT_TEST_FAILURE_HOOKS
1111	    retval |= decrypt_verifySignatureFailure;
1112	#endif
1113	
1114	    return retval;
1115	}
1116	
1117	/* Sets the payload to a pointer inside the chunk buffer. Returns the requestId
1118	 * and the sequenceNumber */
1119	static UA_StatusCode
1120	decryptAndVerifyChunk(const UA_SecureChannel *channel,
1121	                      const UA_SecurityPolicyCryptoModule *cryptoModule,
1122	                      UA_MessageType messageType, const UA_ByteString *chunk,
1123	                      size_t offset, UA_UInt32 *requestId,
1124	                      UA_UInt32 *sequenceNumber, UA_ByteString *payload) {
1125	    size_t chunkSizeAfterDecryption = chunk->length;
1126	    UA_StatusCode retval = decryptChunk(channel, cryptoModule, messageType,
1127	                                        chunk, offset, &chunkSizeAfterDecryption);
1128	    if(retval != UA_STATUSCODE_GOOD)
1129	        return retval;
1130	
1131	    /* Verify the chunk signature */
1132	    size_t sigsize = 0;
1133	    size_t paddingSize = 0;
1134	    const UA_SecurityPolicy *securityPolicy = channel->securityPolicy;
1135	    if(channel->securityMode == UA_MESSAGESECURITYMODE_SIGN ||
1136	       channel->securityMode == UA_MESSAGESECURITYMODE_SIGNANDENCRYPT ||
1137	       messageType == UA_MESSAGETYPE_OPN) {
1138	        sigsize = cryptoModule->signatureAlgorithm.getRemoteSignatureSize(securityPolicy, channel->channelContext);
1139	        retval = getPaddingSize(channel, cryptoModule, messageType, chunk,
1140	                                chunkSizeAfterDecryption, sigsize, &paddingSize);
1141	        if(retval != UA_STATUSCODE_GOOD)
1142	            return retval;
1143	
1144	        if(offset + paddingSize + sigsize >= chunkSizeAfterDecryption)
1145	            return UA_STATUSCODE_BADSECURITYCHECKSFAILED;
1146	
1147	        retval = verifyChunk(channel, cryptoModule, chunk, chunkSizeAfterDecryption, sigsize);
1148	        if(retval != UA_STATUSCODE_GOOD)
1149	            return retval;
1150	    }
1151	
1152	    /* Decode the sequence header */
1153	    UA_SequenceHeader sequenceHeader;
1154	    retval = UA_SequenceHeader_decodeBinary(chunk, &offset, &sequenceHeader);
1155	    if(retval != UA_STATUSCODE_GOOD)
1156	        return retval;
1157	
1158	    if(offset + paddingSize + sigsize >= chunk->length)
1159	        return UA_STATUSCODE_BADSECURITYCHECKSFAILED;
1160	
1161	    *requestId = sequenceHeader.requestId;
1162	    *sequenceNumber = sequenceHeader.sequenceNumber;
1163	    payload->data = chunk->data + offset;
1164	    payload->length = chunkSizeAfterDecryption - offset - sigsize - paddingSize;
1165	    UA_LOG_TRACE_CHANNEL(channel->securityPolicy->logger, channel,
1166	                         "Decrypted and verified chunk with request id %u and sequence number %u",
1167	                         *requestId, *sequenceNumber);
1168	    return UA_STATUSCODE_GOOD;
1169	}
1170	
1171	typedef UA_StatusCode(*UA_SequenceNumberCallback)(UA_SecureChannel *channel,
1172	                                                  UA_UInt32 sequenceNumber);
1173	
1174	static UA_StatusCode
1175	processSequenceNumberAsym(UA_SecureChannel *channel, UA_UInt32 sequenceNumber) {
1176	    UA_LOG_TRACE_CHANNEL(channel->securityPolicy->logger, channel,
1177	                         "Sequence Number processed: %i", sequenceNumber);
1178	    channel->receiveSequenceNumber = sequenceNumber;
1179	    return UA_STATUSCODE_GOOD;
1180	}
1181	
1182	static UA_StatusCode
1183	processSequenceNumberSym(UA_SecureChannel *channel, UA_UInt32 sequenceNumber) {
1184	    /* Failure mode hook for unit tests */
1185	#ifdef UA_ENABLE_UNIT_TEST_FAILURE_HOOKS
1186	    if(processSym_seqNumberFailure != UA_STATUSCODE_GOOD)
1187	        return processSym_seqNumberFailure;
1188	#endif
1189	
1190	    UA_LOG_TRACE_CHANNEL(channel->securityPolicy->logger, channel,
1191	                         "Sequence Number processed: %i", sequenceNumber);
1192	    /* Does the sequence number match? */
1193	    if(sequenceNumber != channel->receiveSequenceNumber + 1) {
1194	        /* FIXME: Remove magic numbers :( */
1195	        if(channel->receiveSequenceNumber + 1 > 4294966271 && sequenceNumber < 1024)
1196	            channel->receiveSequenceNumber = sequenceNumber - 1; /* Roll over */
1197	        else
1198	            return UA_STATUSCODE_BADSECURITYCHECKSFAILED;
1199	    }
1200	    ++channel->receiveSequenceNumber;
1201	    return UA_STATUSCODE_GOOD;
1202	}
1203	
1204	static UA_StatusCode
1205	checkAsymHeader(UA_SecureChannel *const channel,
1206	                UA_AsymmetricAlgorithmSecurityHeader *const asymHeader) {
1207	    UA_StatusCode retval = UA_STATUSCODE_GOOD;
1208	    const UA_SecurityPolicy *const securityPolicy = channel->securityPolicy;
1209	
1210	    if(!UA_ByteString_equal(&securityPolicy->policyUri,
1211	                            &asymHeader->securityPolicyUri)) {
1212	        return UA_STATUSCODE_BADSECURITYPOLICYREJECTED;
1213	    }
1214	
1215	    // TODO: Verify certificate using certificate plugin. This will come with a new PR
1216	    /* Something like this
1217	    retval = certificateManager->verify(certificateStore??, &asymHeader->senderCertificate);
1218	    if(retval != UA_STATUSCODE_GOOD)
1219	    return retval;
1220	    */
1221	    retval = securityPolicy->asymmetricModule.
1222	        compareCertificateThumbprint(securityPolicy,
1223	                                     &asymHeader->receiverCertificateThumbprint);
1224	    if(retval != UA_STATUSCODE_GOOD) {
1225	        return retval;
1226	    }
1227	
1228	    return UA_STATUSCODE_GOOD;
1229	}
1230	
1231	static UA_StatusCode
1232	checkPreviousToken(UA_SecureChannel *const channel, const UA_UInt32 tokenId) {
1233	    if(tokenId != channel->previousSecurityToken.tokenId)
1234	        return UA_STATUSCODE_BADSECURECHANNELTOKENUNKNOWN;
1235	
1236	    UA_DateTime timeout = channel->previousSecurityToken.createdAt +
1237	                          (UA_DateTime)((UA_Double)channel->previousSecurityToken.revisedLifetime *
1238	                                        (UA_Double)UA_DATETIME_MSEC *
1239	                                        1.25);
1240	
1241	    if(timeout < UA_DateTime_nowMonotonic())
1242	        return UA_STATUSCODE_BADSECURECHANNELTOKENUNKNOWN;
1243	
1244	    return UA_STATUSCODE_GOOD;
1245	}
1246	
1247	static UA_StatusCode
1248	checkSymHeader(UA_SecureChannel *const channel,
1249	               const UA_UInt32 tokenId, UA_Boolean allowPreviousToken) {
1250	
1251	    if(tokenId == channel->securityToken.tokenId) {
1252	        if(channel->state == UA_SECURECHANNELSTATE_OPEN &&
1253	           (channel->securityToken.createdAt +
1254	            (channel->securityToken.revisedLifetime * UA_DATETIME_MSEC))
1255	           < UA_DateTime_nowMonotonic()) {
1256	            UA_SecureChannel_close(channel);
1257	            return UA_STATUSCODE_BADSECURECHANNELCLOSED;
1258	        }
1259	    }
1260	
1261	    if(tokenId != channel->securityToken.tokenId) {
1262	        if(tokenId != channel->nextSecurityToken.tokenId) {
1263	            if(allowPreviousToken)
1264	                return checkPreviousToken(channel, tokenId);
1265	            else
1266	                return UA_STATUSCODE_BADSECURECHANNELTOKENUNKNOWN;
1267	        }
1268	        return UA_SecureChannel_revolveTokens(channel);
1269	    }
1270	
1271	    if(channel->previousSecurityToken.tokenId != 0) {
1272	        UA_StatusCode retval =
1273	            UA_SecureChannel_generateRemoteKeys(channel, channel->securityPolicy);
1274	        UA_ChannelSecurityToken_deleteMembers(&channel->previousSecurityToken);
1275	        return retval;
1276	    }
1277	
1278	    return UA_STATUSCODE_GOOD;
1279	}
1280	
1281	static UA_StatusCode
1282	putPayload(UA_SecureChannel *const channel, UA_UInt32 const requestId,
1283	           UA_MessageType const messageType, UA_ChunkType const chunkType,
1284	           UA_ByteString *chunkPayload) {
1285	    switch(chunkType) {
1286	    case UA_CHUNKTYPE_INTERMEDIATE:
1287	    case UA_CHUNKTYPE_FINAL:
1288	        return addChunkPayload(channel, requestId, messageType,
1289	                               chunkPayload, chunkType == UA_CHUNKTYPE_FINAL);
1290	    case UA_CHUNKTYPE_ABORT:
1291	        deleteLatestMessage(channel, requestId);
1292	        return UA_STATUSCODE_GOOD;
1293	    default:
1294	        return UA_STATUSCODE_BADTCPMESSAGETYPEINVALID;
1295	    }
1296	}
1297	
1298	/* The chunk body begins after the SecureConversationMessageHeader */
1299	static UA_StatusCode
1300	decryptAddChunk(UA_SecureChannel *channel, const UA_ByteString *chunk,
1301	                UA_Boolean allowPreviousToken) {
1302	    /* Decode the MessageHeader */
1303	    size_t offset = 0;
1304	    UA_SecureConversationMessageHeader messageHeader;
1305	    UA_StatusCode retval =
1306	        UA_SecureConversationMessageHeader_decodeBinary(chunk, &offset, &messageHeader);
1307	    if(retval != UA_STATUSCODE_GOOD)
1308	        return retval;
1309	
1310	#if !defined(FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION)
1311	    /* The wrong ChannelId. Non-opened channels have the id zero. */
1312	    if(messageHeader.secureChannelId != channel->securityToken.channelId &&
1313	       channel->state != UA_SECURECHANNELSTATE_FRESH)
1314	        return UA_STATUSCODE_BADSECURECHANNELIDINVALID;
1315	#endif
1316	
1317	    UA_MessageType messageType = (UA_MessageType)
1318	        (messageHeader.messageHeader.messageTypeAndChunkType & UA_BITMASK_MESSAGETYPE);
1319	    UA_ChunkType chunkType = (UA_ChunkType)
1320	        (messageHeader.messageHeader.messageTypeAndChunkType & UA_BITMASK_CHUNKTYPE);
1321	    UA_UInt32 requestId = 0;
1322	    UA_UInt32 sequenceNumber = 0;
1323	    UA_ByteString chunkPayload;
1324	    const UA_SecurityPolicyCryptoModule *cryptoModule = NULL;
1325	    UA_SequenceNumberCallback sequenceNumberCallback = NULL;
1326	
1327	    switch(messageType) {
1328	        /* ERR message (not encrypted) */
1329	    case UA_MESSAGETYPE_ERR:
1330	        if(chunkType != UA_CHUNKTYPE_FINAL)
1331	            return UA_STATUSCODE_BADTCPMESSAGETYPEINVALID;
1332	        chunkPayload.length = chunk->length - offset;
1333	        chunkPayload.data = chunk->data + offset;
1334	        return putPayload(channel, requestId, messageType, chunkType, &chunkPayload);
1335	
1336	        /* MSG and CLO: Symmetric encryption */
1337	    case UA_MESSAGETYPE_MSG:
1338	    case UA_MESSAGETYPE_CLO: {
1339	        /* Decode and check the symmetric security header (tokenId) */
1340	        UA_SymmetricAlgorithmSecurityHeader symmetricSecurityHeader;
1341	        UA_SymmetricAlgorithmSecurityHeader_init(&symmetricSecurityHeader);
1342	        retval = UA_SymmetricAlgorithmSecurityHeader_decodeBinary(chunk, &offset,
1343	                                                                  &symmetricSecurityHeader);
1344	        if(retval != UA_STATUSCODE_GOOD)
1345	            return retval;
1346	
1347	#ifdef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
1348	        /* Help fuzzing by always setting the correct tokenId */
1349	        symmetricSecurityHeader.tokenId = channel->securityToken.tokenId;
1350	#endif
1351	
1352	        retval = checkSymHeader(channel, symmetricSecurityHeader.tokenId, allowPreviousToken);
1353	        if(retval != UA_STATUSCODE_GOOD)
1354	            return retval;
1355	
1356	        cryptoModule = &channel->securityPolicy->symmetricModule.cryptoModule;
1357	        sequenceNumberCallback = processSequenceNumberSym;
1358	        break;
1359	    }
1360	
1361	        /* OPN: Asymmetric encryption */
1362	    case UA_MESSAGETYPE_OPN: {
1363	        /* Chunking not allowed for OPN */
1364	        if(chunkType != UA_CHUNKTYPE_FINAL)
1365	            return UA_STATUSCODE_BADTCPMESSAGETYPEINVALID;
1366	
1367	        /* Decode the asymmetric algorithm security header and call the callback
1368	         * to perform checks. */
1369	        UA_AsymmetricAlgorithmSecurityHeader asymHeader;
1370	        UA_AsymmetricAlgorithmSecurityHeader_init(&asymHeader);
1371	        offset = UA_SECURE_CONVERSATION_MESSAGE_HEADER_LENGTH;
1372	        retval = UA_AsymmetricAlgorithmSecurityHeader_decodeBinary(chunk, &offset, &asymHeader);
1373	        if(retval != UA_STATUSCODE_GOOD)
1374	            return retval;
1375	
1376	        retval = checkAsymHeader(channel, &asymHeader);
1377	        UA_AsymmetricAlgorithmSecurityHeader_deleteMembers(&asymHeader);
1378	        if(retval != UA_STATUSCODE_GOOD)
1379	            return retval;
1380	
1381	        cryptoModule = &channel->securityPolicy->asymmetricModule.cryptoModule;
1382	        sequenceNumberCallback = processSequenceNumberAsym;
1383	        break;
1384	    }
1385	
1386	        /* Invalid message type */
1387	    default:return UA_STATUSCODE_BADTCPMESSAGETYPEINVALID;
1388	    }
1389	
1390	    UA_assert(cryptoModule != NULL);
1391	    retval = decryptAndVerifyChunk(channel, cryptoModule, messageType, chunk, offset,
1392	                                   &requestId, &sequenceNumber, &chunkPayload);
1393	    if(retval != UA_STATUSCODE_GOOD)
1394	        return retval;
1395	
1396	    /* Check the sequence number. Skip sequence number checking for fuzzer to
1397	     * improve coverage */
1398	    if(sequenceNumberCallback == NULL)
1399	        return UA_STATUSCODE_BADINTERNALERROR;
1400	#if defined(FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION)
1401	    retval = UA_STATUSCODE_GOOD;
1402	#else
1403	    retval = sequenceNumberCallback(channel, sequenceNumber);
1404	#endif
1405	    if(retval != UA_STATUSCODE_GOOD)
1406	        return retval;
1407	
1408	    return putPayload(channel, requestId, messageType, chunkType, &chunkPayload);
1409	}
1410	
1411	UA_StatusCode
1412	UA_SecureChannel_decryptAddChunk(UA_SecureChannel *channel, const UA_ByteString *chunk,
1413	                                 UA_Boolean allowPreviousToken) {
1414	    /* Has the SecureChannel timed out? */
1415	    if(channel->state == UA_SECURECHANNELSTATE_CLOSED)
1416	        return UA_STATUSCODE_BADSECURECHANNELCLOSED;
1417	
1418	    /* Is the SecureChannel configured? */
1419	    if(!channel->connection)
1420	        return UA_STATUSCODE_BADINTERNALERROR;
1421	
1422	    UA_StatusCode retval = decryptAddChunk(channel, chunk, allowPreviousToken);
1423	    if(retval != UA_STATUSCODE_GOOD)
1424	        UA_SecureChannel_close(channel);
1425	
1426	    return retval;
1427	}
1428	
1429	UA_StatusCode
1430	UA_SecureChannel_persistIncompleteMessages(UA_SecureChannel *channel) {
1431	    UA_Message *me;
1432	    TAILQ_FOREACH(me, &channel->messages, pointers) {
1433	        UA_ChunkPayload *cp;
1434	        SIMPLEQ_FOREACH(cp, &me->chunkPayloads, pointers) {
1435	            if(cp->copied)
1436	                continue;
1437	            UA_ByteString copy;
1438	            UA_StatusCode retval = UA_ByteString_copy(&cp->bytes, &copy);
1439	            if(retval != UA_STATUSCODE_GOOD) {
1440	                UA_SecureChannel_close(channel);
1441	                return retval;
1442	            }
1443	            cp->bytes = copy;
1444	            cp->copied = true;
1445	        }
1446	    }
1447	    return UA_STATUSCODE_GOOD;
1448	}
1449	
1450	/* Functionality used by both the SecureChannel and the SecurityPolicy */
1451	
1452	size_t
1453	UA_SecurityPolicy_getRemoteAsymEncryptionBufferLengthOverhead(const UA_SecurityPolicy *securityPolicy,
1454	                                                              const void *channelContext,
1455	                                                              size_t maxEncryptionLength) {
1456	    if(maxEncryptionLength == 0)
1457	        return 0;
1458	
1459	    size_t plainTextBlockSize = securityPolicy->asymmetricModule.cryptoModule.encryptionAlgorithm.
1460	        getRemotePlainTextBlockSize(securityPolicy, channelContext);
1461	    size_t encryptedBlockSize = securityPolicy->asymmetricModule.cryptoModule.encryptionAlgorithm.
1462	        getRemoteBlockSize(securityPolicy, channelContext);
1463	    if(plainTextBlockSize == 0)
1464	        return 0;
1465	
1466	    size_t maxNumberOfBlocks = maxEncryptionLength / plainTextBlockSize;
1467	    return maxNumberOfBlocks * (encryptedBlockSize - plainTextBlockSize);
1468	}
