/* HEL -> Open up the connection */
static UA_StatusCode
processHEL(UA_Server *server, UA_Connection *connection,
           const UA_ByteString *msg, size_t *offset) {
    UA_TcpHelloMessage helloMessage;
    UA_StatusCode retval = UA_TcpHelloMessage_decodeBinary(msg, offset, &helloMessage);
    if(retval != UA_STATUSCODE_GOOD)
        return retval;

    /* Currently not checked */
    UA_String_deleteMembers(&helloMessage.endpointUrl);

    /* TODO: Use the config of the exact NetworkLayer */
    if(server->config.networkLayersSize == 0)
        return UA_STATUSCODE_BADOUTOFMEMORY;
    const UA_ConnectionConfig *localConfig = &server->config.networkLayers[0].localConnectionConfig;

    /* Parameterize the connection */
    UA_ConnectionConfig remoteConfig;
    remoteConfig.protocolVersion = helloMessage.protocolVersion;
    remoteConfig.sendBufferSize = helloMessage.sendBufferSize;
    remoteConfig.recvBufferSize = helloMessage.receiveBufferSize;
    remoteConfig.maxMessageSize = helloMessage.maxMessageSize;
    remoteConfig.maxChunkCount = helloMessage.maxChunkCount;
    retval = UA_Connection_processHELACK(connection, localConfig, &remoteConfig);
    if(retval != UA_STATUSCODE_GOOD) {
        UA_LOG_INFO(server->config.logger, UA_LOGCATEGORY_NETWORK,
                    "Connection %i | Error during the HEL/ACK handshake",
                    (int)(connection->sockfd));

content.content:
300	        return retval;
301	    }
302	
303	    /* Build acknowledge response */
304	    UA_TcpAcknowledgeMessage ackMessage;
305	    memcpy(&ackMessage, localConfig, sizeof(UA_TcpAcknowledgeMessage)); /* Same struct layout.. */
306	    UA_TcpMessageHeader ackHeader;
307	    ackHeader.messageTypeAndChunkType = UA_MESSAGETYPE_ACK + UA_CHUNKTYPE_FINAL;
308	    ackHeader.messageSize = 8 + 20; /* ackHeader + ackMessage */
309	
310	    /* Get the send buffer from the network layer */
311	    UA_ByteString ack_msg;
312	    UA_ByteString_init(&ack_msg);
313	    retval = connection->getSendBuffer(connection, connection->config.sendBufferSize, &ack_msg);
314	    if(retval != UA_STATUSCODE_GOOD)
315	        return retval;
316	
317	    /* Encode and send the response */
318	    UA_Byte *bufPos = ack_msg.data;
319	    const UA_Byte *bufEnd = &ack_msg.data[ack_msg.length];
320	
321	    retval = UA_TcpMessageHeader_encodeBinary(&ackHeader, &bufPos, bufEnd);
322	    if(retval != UA_STATUSCODE_GOOD) {
323	        connection->releaseSendBuffer(connection, &ack_msg);
324	        return retval;
325	    }
326	
327	    retval = UA_TcpAcknowledgeMessage_encodeBinary(&ackMessage, &bufPos, bufEnd);
328	    if(retval != UA_STATUSCODE_GOOD) {
329	        connection->releaseSendBuffer(connection, &ack_msg);
330	        return retval;
331	    }
332	    ack_msg.length = ackHeader.messageSize;
333	    return connection->send(connection, &ack_msg);
334	}
