13	#include "ua_securechannel_manager.h"
14	#include "ua_session.h"
15	#include "ua_server_internal.h"
16	#include "ua_transport_generated_handling.h"
17	
18	#define STARTCHANNELID 1
19	#define STARTTOKENID 1
20	
21	UA_StatusCode
22	UA_SecureChannelManager_init(UA_SecureChannelManager *cm, UA_Server *server) {
23	    TAILQ_INIT(&cm->channels);
24	    // TODO: use an ID that is likely to be unique after a restart
25	    cm->lastChannelId = STARTCHANNELID;
26	    cm->lastTokenId = STARTTOKENID;
27	    cm->currentChannelCount = 0;
28	    cm->server = server;
29	    return UA_STATUSCODE_GOOD;
30	}
31	
32	void
33	UA_SecureChannelManager_deleteMembers(UA_SecureChannelManager *cm) {
34	    channel_entry *entry, *temp;
35	    TAILQ_FOREACH_SAFE(entry, &cm->channels, pointers, temp) {
36	        TAILQ_REMOVE(&cm->channels, entry, pointers);
37	        UA_SecureChannel_close(&entry->channel);
38	        UA_SecureChannel_deleteMembers(&entry->channel);
39	        UA_free(entry);
