43	static void
44	removeSecureChannelCallback(void *_, channel_entry *entry) {
45	    UA_SecureChannel_deleteMembers(&entry->channel);
46	}
47	
48	static void
49	removeSecureChannel(UA_SecureChannelManager *cm, channel_entry *entry) {
50	    /* Close the SecureChannel */
51	    UA_SecureChannel_close(&entry->channel);
52	
53	    /* Detach the channel and make the capacity available */
54	    TAILQ_REMOVE(&cm->channels, entry, pointers);
55	    UA_atomic_subUInt32(&cm->currentChannelCount, 1);
56	
57	    /* Add a delayed callback to remove the channel when the currently
58	     * scheduled jobs have completed */
59	    entry->cleanupCallback.callback = (UA_ApplicationCallback)removeSecureChannelCallback;
60	    entry->cleanupCallback.application = NULL;
61	    entry->cleanupCallback.data = entry;
62	    UA_WorkQueue_enqueueDelayed(&cm->server->workQueue, &entry->cleanupCallback);
63	}
64	
65	/* remove channels that were not renewed or who have no connection attached */
66	void
67	UA_SecureChannelManager_cleanupTimedOut(UA_SecureChannelManager *cm,
68	                                        UA_DateTime nowMonotonic) {
69	    channel_entry *entry, *temp;
70	    TAILQ_FOREACH_SAFE(entry, &cm->channels, pointers, temp) {
71	        /* The channel was closed internally */
72	        if(entry->channel.state == UA_SECURECHANNELSTATE_CLOSED ||
73	           !entry->channel.connection) {
74	            removeSecureChannel(cm, entry);
75	            continue;
76	        }
77	
78	        /* The channel has timed out */
79	        UA_DateTime timeout =
80	            entry->channel.securityToken.createdAt +
81	            (UA_DateTime)(entry->channel.securityToken.revisedLifetime * UA_DATETIME_MSEC);
82	        if(timeout < nowMonotonic) {
83	            UA_LOG_INFO_CHANNEL(cm->server->config.logger, &entry->channel,
84	                                "SecureChannel has timed out");
85	            removeSecureChannel(cm, entry);
86	            continue;
87	        }
88	
89	        /* Revolve the channel tokens */
90	        if(entry->channel.nextSecurityToken.tokenId > 0) {
91	            UA_SecureChannel_revolveTokens(&entry->channel);
92	        }
93	    }
94	}
95	
96	/* remove the first channel that has no session attached */
97	static UA_Boolean
98	purgeFirstChannelWithoutSession(UA_SecureChannelManager *cm) {
99	    channel_entry *entry;
100	    TAILQ_FOREACH(entry, &cm->channels, pointers) {
101	        if(LIST_EMPTY(&entry->channel.sessions)) {
102	            UA_LOG_INFO_CHANNEL(cm->server->config.logger, &entry->channel,
103	                                "Channel was purged since maxSecureChannels was "
104	                                "reached and channel had no session attached");
105	            removeSecureChannel(cm, entry);
106	            return true;
107	        }
108	    }
109	    return false;
110	}
111	
112	UA_StatusCode
113	UA_SecureChannelManager_create(UA_SecureChannelManager *const cm, UA_Connection *const connection,
114	                               const UA_SecurityPolicy *const securityPolicy,
115	                               const UA_AsymmetricAlgorithmSecurityHeader *const asymHeader) {
116	    /* connection already has a channel attached. */
117	    if(connection->channel != NULL)
118	        return UA_STATUSCODE_BADINTERNALERROR;
119	
120	    /* Check if there exists a free SC, otherwise try to purge one SC without a
121	     * session the purge has been introduced to pass CTT, it is not clear what
122	     * strategy is expected here */
123	    if(cm->currentChannelCount >= cm->server->config.maxSecureChannels &&
124	       !purgeFirstChannelWithoutSession(cm))
125	        return UA_STATUSCODE_BADOUTOFMEMORY;
126	
127	    UA_LOG_INFO(cm->server->config.logger, UA_LOGCATEGORY_SECURECHANNEL,
128	                "Creating a new SecureChannel");
129	
130	    channel_entry *entry = (channel_entry *)UA_malloc(sizeof(channel_entry));
131	    if(!entry)
132	        return UA_STATUSCODE_BADOUTOFMEMORY;
133	
134	    /* Create the channel context and parse the sender (remote) certificate used for the
135	     * secureChannel. */
136	    UA_SecureChannel_init(&entry->channel);
137	    UA_StatusCode retval =
138	        UA_SecureChannel_setSecurityPolicy(&entry->channel, securityPolicy,
139	                                           &asymHeader->senderCertificate);
140	    if(retval != UA_STATUSCODE_GOOD) {
141	        UA_free(entry);
142	        return retval;
143	    }
144	
145	    /* Channel state is fresh (0) */
146	    entry->channel.securityToken.channelId = 0;
147	    entry->channel.securityToken.tokenId = cm->lastTokenId++;
148	    entry->channel.securityToken.createdAt = UA_DateTime_now();
149	    entry->channel.securityToken.revisedLifetime = cm->server->config.maxSecurityTokenLifetime;
150	
151	    TAILQ_INSERT_TAIL(&cm->channels, entry, pointers);
152	    UA_atomic_addUInt32(&cm->currentChannelCount, 1);
153	    UA_Connection_attachSecureChannel(connection, &entry->channel);
154	    return UA_STATUSCODE_GOOD;
155	}
156	
157	UA_StatusCode
158	UA_SecureChannelManager_open(UA_SecureChannelManager *cm, UA_SecureChannel *channel,
159	                             const UA_OpenSecureChannelRequest *request,
160	                             UA_OpenSecureChannelResponse *response) {
161	    if(channel->state != UA_SECURECHANNELSTATE_FRESH) {
162	        UA_LOG_ERROR_CHANNEL(cm->server->config.logger, channel,
163	                             "Called open on already open or closed channel");
164	        return UA_STATUSCODE_BADINTERNALERROR;
165	    }
166	
167	    if(request->securityMode != UA_MESSAGESECURITYMODE_NONE &&
168	       UA_ByteString_equal(&channel->securityPolicy->policyUri, &UA_SECURITY_POLICY_NONE_URI)) {
169	        return UA_STATUSCODE_BADSECURITYMODEREJECTED;
170	    }
171	
172	    channel->securityMode = request->securityMode;
173	    channel->securityToken.createdAt = UA_DateTime_nowMonotonic();
174	    channel->securityToken.channelId = cm->lastChannelId++;
175	    channel->securityToken.createdAt = UA_DateTime_now();
176	
177	    /* Set the lifetime. Lifetime 0 -> set the maximum possible */
178	    channel->securityToken.revisedLifetime =
179	        (request->requestedLifetime > cm->server->config.maxSecurityTokenLifetime) ?
180	        cm->server->config.maxSecurityTokenLifetime : request->requestedLifetime;
181	    if(channel->securityToken.revisedLifetime == 0)
182	        channel->securityToken.revisedLifetime = cm->server->config.maxSecurityTokenLifetime;
183	
184	    /* Set the nonces and generate the keys */
185	    UA_StatusCode retval = UA_ByteString_copy(&request->clientNonce, &channel->remoteNonce);
186	    if(retval != UA_STATUSCODE_GOOD)
187	        return retval;
188	
189	    retval = UA_SecureChannel_generateLocalNonce(channel);
190	    if(retval != UA_STATUSCODE_GOOD)
191	        return retval;
192	
193	    retval = UA_SecureChannel_generateNewKeys(channel);
194	    if(retval != UA_STATUSCODE_GOOD)
195	        return retval;
196	
197	    /* Set the response */
198	    retval = UA_ByteString_copy(&channel->localNonce, &response->serverNonce);
199	    if(retval != UA_STATUSCODE_GOOD)
200	        return retval;
201	
202	    retval = UA_ChannelSecurityToken_copy(&channel->securityToken, &response->securityToken);
203	    if(retval != UA_STATUSCODE_GOOD)
204	        return retval;
205	
206	    response->responseHeader.timestamp = UA_DateTime_now();
207	    response->responseHeader.requestHandle = request->requestHeader.requestHandle;
208	
209	    /* The channel is open */
210	    channel->state = UA_SECURECHANNELSTATE_OPEN;
211	
212	    return UA_STATUSCODE_GOOD;
213	}
214	
215	UA_StatusCode
216	UA_SecureChannelManager_renew(UA_SecureChannelManager *cm, UA_SecureChannel *channel,
217	                              const UA_OpenSecureChannelRequest *request,
218	                              UA_OpenSecureChannelResponse *response) {
219	    if(channel->state != UA_SECURECHANNELSTATE_OPEN) {
220	        UA_LOG_ERROR_CHANNEL(cm->server->config.logger, channel,
221	                             "Called renew on channel which is not open");
222	        return UA_STATUSCODE_BADINTERNALERROR;
223	    }
224	
225	    /* If no security token is already issued */
226	    if(channel->nextSecurityToken.tokenId == 0) {
227	        channel->nextSecurityToken.channelId = channel->securityToken.channelId;
228	        channel->nextSecurityToken.tokenId = cm->lastTokenId++;
229	        channel->nextSecurityToken.createdAt = UA_DateTime_now();
230	        channel->nextSecurityToken.revisedLifetime =
231	            (request->requestedLifetime > cm->server->config.maxSecurityTokenLifetime) ?
232	            cm->server->config.maxSecurityTokenLifetime : request->requestedLifetime;
233	        if(channel->nextSecurityToken.revisedLifetime == 0) /* lifetime 0 -> return the max lifetime */
234	            channel->nextSecurityToken.revisedLifetime = cm->server->config.maxSecurityTokenLifetime;
235	    }
236	
237	    /* Replace the nonces */
238	    UA_ByteString_deleteMembers(&channel->remoteNonce);
239	    UA_StatusCode retval = UA_ByteString_copy(&request->clientNonce, &channel->remoteNonce);
240	    if(retval != UA_STATUSCODE_GOOD)
241	        return retval;
242	
243	    retval = UA_SecureChannel_generateLocalNonce(channel);
244	    if(retval != UA_STATUSCODE_GOOD)
245	        return retval;
246	
247	    /* Set the response */
248	    response->responseHeader.requestHandle = request->requestHeader.requestHandle;
249	    retval = UA_ByteString_copy(&channel->localNonce, &response->serverNonce);
250	    if(retval != UA_STATUSCODE_GOOD)
251	        return retval;
252	
253	    retval = UA_ChannelSecurityToken_copy(&channel->nextSecurityToken, &response->securityToken);
254	    if(retval != UA_STATUSCODE_GOOD)
255	        return retval;
256	
257	    /* Reset the internal creation date to the monotonic clock */
258	    channel->nextSecurityToken.createdAt = UA_DateTime_nowMonotonic();
259	    return UA_STATUSCODE_GOOD;
260	}
261	
262	UA_SecureChannel *
263	UA_SecureChannelManager_get(UA_SecureChannelManager *cm, UA_UInt32 channelId) {
264	    channel_entry *entry;
265	    TAILQ_FOREACH(entry, &cm->channels, pointers) {
266	        if(entry->channel.securityToken.channelId == channelId)
267	            return &entry->channel;
268	    }
269	    return NULL;
270	}
271	
272	UA_StatusCode
273	UA_SecureChannelManager_close(UA_SecureChannelManager *cm, UA_UInt32 channelId) {
274	    channel_entry *entry;
275	    TAILQ_FOREACH(entry, &cm->channels, pointers) {
276	        if(entry->channel.securityToken.channelId == channelId)
277	            break;
278	    }
279	    if(!entry)
280	        return UA_STATUSCODE_BADINTERNALERROR;
281	
282	    removeSecureChannel(cm, entry);
283	    return UA_STATUSCODE_GOOD;
284	}
